import { useId, useRef, type KeyboardEvent } from "react";
import "./SegmentedControl.css";

export interface SegmentedOption<T extends string = string> {
  value: T;
  label: string;
}

export interface SegmentedControlProps<T extends string = string> {
  label: string;
  options: readonly SegmentedOption<T>[];
  value: T;
  onChange: (value: T) => void;
}

export function SegmentedControl<T extends string>({
  label,
  options,
  value,
  onChange,
}: SegmentedControlProps<T>) {
  const labelId = useId();
  const buttonRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const selectedIndex = options.findIndex((option) => option.value === value);
  // Roving tabindex: only the selected segment is in the Tab order.
  // If nothing matches, the first segment takes that role.
  const tabStopIndex = selectedIndex >= 0 ? selectedIndex : 0;

  const select = (index: number) => {
    const option = options[index];
    if (!option) return;
    buttonRefs.current[index]?.focus();
    if (option.value !== value) {
      onChange(option.value);
    }
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const count = options.length;
    if (count === 0) return;

    let next: number;
    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        next = (index + 1) % count;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        next = (index - 1 + count) % count;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = count - 1;
        break;
      default:
        return;
    }

    event.preventDefault();
    select(next);
  };

  return (
    <div className="seg-root">
      <span id={labelId} className="seg-label">
        {label}
      </span>
      <div role="radiogroup" aria-labelledby={labelId} className="seg-track">
        {options.map((option, index) => {
          const isSelected = index === selectedIndex;
          return (
            <button
              key={option.value}
              ref={(element) => {
                buttonRefs.current[index] = element;
              }}
              type="button"
              role="radio"
              aria-checked={isSelected}
              tabIndex={index === tabStopIndex ? 0 : -1}
              className={isSelected ? "seg-option seg-option--selected" : "seg-option"}
              onClick={() => select(index)}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}
