  display: inline-flex;
  align-items: stretch;
  gap: 2px;
  padding: 3px;
  border-radius: 999px;
  background-color: var(--seg-track-bg);
  box-shadow: inset 0 0 0 1px var(--seg-track-border);
}

.seg-option {
  flex: 1 1 0;
  min-height: 32px;
  min-width: 0;
  margin: 0;
  padding: 6px 14px;
  border: none;
  border-radius: 999px;
  background-color: transparent;
  color: var(--seg-option-text);
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.2;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  transition:
    background-color 150ms ease,
    color 150ms ease,
    box-shadow 150ms ease;
}

.seg-option:hover {
  color: var(--seg-option-hover-text);
}

.seg-option--selected,
.seg-option--selected:hover {
  background-color: var(--seg-selected-bg);
  color: var(--seg-selected-text);
  font-weight: 600;
  box-shadow: var(--seg-selected-shadow);
}

.seg-option:focus {
  outline: none;
}

.seg-option:focus-visible {
  outline: 2px solid var(--seg-focus-ring);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .seg-option {
    transition: none;
  }
}
